SUPERADMIN = {
    'username': 'superadmin',
    'email': 'superadmin@gmail.com',
    'role_code': 'SUPER_ADMIN',
}

class Command(BaseCommand):
    help = "Seed page permissions, roles, and a superadmin account. Idempotent."

    def add_arguments(self, parser):
        parser.add_argument('--reset-password', action='store_true', help='Reset the superadmin password (requires env var DJANGO_SUPERADMIN_PASSWORD)')

    def handle(self, *args, **options):
        with transaction.atomic():
            self._seed_permissions()
            self._seed_roles()
            self._seed_superadmin(reset_password=options['reset_password'])

    def _seed_permissions(self):
        created = skipped = 0
        for perm in PAGE_PERMISSIONS:
            obj, was_created = PagePermission.objects.get_or_create(
                code=perm['code'],
                defaults={
                    'name': perm['name'],
                    'module': perm['module'],
                    'icon': perm.get('icon') or '',
                    'description': perm.get('description') or '',
                },
            )
            if was_created:
                created += 1
            else:
                skipped += 1
        self.stdout.write(f"PagePermissions: {created} created, {skipped} already present")

    def _seed_roles(self):
        created = skipped = 0
        for role in ROLES:
            role_obj, was_created = Role.objects.get_or_create(
                code=role['code'],
                defaults={
                    'name': role['name'],
                    'description': role.get('description') or '',
                    'is_system_role': role.get('is_system_role', False),
                },
            )
            perm_objs = PagePermission.objects.filter(code__in=role['permission_codes'])
            role_obj.permissions.add(*perm_objs)
            if was_created:
                created += 1
            else:
                skipped += 1
        self.stdout.write(f"Roles: {created} created, {skipped} already present")

    def _seed_superadmin(self, reset_password=False):
        import os
        user, was_created = User.objects.get_or_create(
            username=SUPERADMIN['username'],
            defaults={
                'email': SUPERADMIN['email'],
                'is_superuser': True,
                'is_staff': True,
                'is_active': True,
            },
        )
        user.is_superuser = True
        user.is_staff = True
        user.is_active = True
        user.role = Role.objects.get(code=SUPERADMIN['role_code'])

        if was_created:
            password = os.environ.get('DJANGO_SUPERADMIN_PASSWORD')
            if not password:
                self.stdout.write(self.style.WARNING(
                    "WARNING: superadmin created with unusable password. "
                    "Set DJANGO_SUPERADMIN_PASSWORD env var and re-run, or use --reset-password."
                ))
                user.set_unusable_password()
            else:
                user.set_password(password)
            self.stdout.write(self.style.SUCCESS(f"Created superadmin: {user.username}"))
        elif reset_password:
            password = os.environ.get('DJANGO_SUPERADMIN_PASSWORD')
            if not password:
                raise SystemExit("--reset-password requires DJANGO_SUPERADMIN_PASSWORD to be set")
            user.set_password(password)
            self.stdout.write(self.style.SUCCESS(f"Reset superadmin password: {user.username}"))
        else:
            self.stdout.write(f"Superadmin '{user.username}' already exists — password unchanged")

        user.save()
